Given a binary tree, write an iterative function to print the Preorder traversal of the tree. The Preorder traversal follows the order: Root → Left → Right.Examples:Input:           1         /   \        2     3      /  \     4    5Output: 1 2 4 5 3Explanation: Preorder traversal (Root->Left->Right) of the tree is 1 2 4 5 3.Input:            8          /   \         1      5          \    /  \           7  10   6            \  /            10 6Output: 8 1 7 10 5 10 6 6 Explanation:Preorder traversal (Root->Left->Right) of the tree is 8 1 7 10 5 10 6 6.Try It YourselfTable of Content[Naive Approach] Simple Iterative Preorder (with stack) - O(n) time and O(n) space[Better Approach] Iterative Preorder with Current Pointer (with stack) - O(n) time and O(n) space[Expected Approach] Preorder Morris Traversal - O(n) time and O(1) space[Naive Approach] Simple Iterative Preorder (with stack) - O(n) time and O(n) spaceFollowing is a simple stack based iterative process to print Preorder traversal. Create an empty stack and push root node to stack. Do the following while is not empty. Pop an item from the stack and print it. Push right child of a popped item to stack Push left child of a popped item to stackThe right child is pushed before the left child to make sure that the left subtree is processed first.
            C++

    #include <iostream>
#include <vector>
#include <stack>

using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = right = nullptr; 
    }
};

vector<int> preOrder(Node* root) {
    vector<int> res;
    if (root == nullptr)
        return res;

    stack<Node*> s;
    s.push(root);

    while (!s.empty()) {
        Node* curr = s.top();
        s.pop();
        res.push_back(curr->data);

        if (curr->right != nullptr)
            s.push(curr->right);
        if (curr->left != nullptr)
            s.push(curr->left);
    }

    return res;
}

int main() {
    Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);

    vector<int> preorder = preOrder(root);

    for (int val : preorder) {
        cout << val << " ";
    }
    cout << endl;

    return 0;
}


